import{_ as s,o as i,c as e,a2 as n}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"@Sync 与 @LazySync 注解及同步管理器","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.11/sync/index.md","filePath":"1.21.11/sync/index.md"}'),t={name:"1.21.11/sync/index.md"};function c(d,a,l,o,r,h){return i(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="sync-与-lazysync-注解及同步管理器" tabindex="-1"><code>@Sync</code> 与 <code>@LazySync</code> 注解及同步管理器 <a class="header-anchor" href="#sync-与-lazysync-注解及同步管理器" aria-label="Permalink to &quot;`@Sync` 与 `@LazySync` 注解及同步管理器&quot;">​</a></h1><p><code>module.sync</code> 为 Mod 开发者提供了无需手写样板网络数据包即可跨端同步实体、方块实体及静态类中字段数据的声明式框架：</p><ul><li><strong><code>@Sync</code></strong>：作用于类注解（<code>ElementType.TYPE</code>），由编译期/类加载变换与 <code>SyncTargetIndex</code> 协作，对类下需要同步字段的读写操作自动路由或挂载 <code>SyncProxy</code> 实时发包。</li><li><strong><code>@LazySync</code></strong>：作用于字段注解（<code>ElementType.FIELD</code>，<code>RetentionPolicy.RUNTIME</code>），由运行时管理器 <code>LazySyncManager</code> 在每 Tick 结束时按对象比对字节快照，同一 Tick 内一个目标对象只打包发送一次全部变更字段。</li></ul><h2 id="模块标识与核心类" tabindex="-1">模块标识与核心类 <a class="header-anchor" href="#模块标识与核心类" aria-label="Permalink to &quot;模块标识与核心类&quot;">​</a></h2><ul><li>模组 ID：<code>anvillib_sync</code>（<code>AnvilLibSync.MOD_ID</code>）</li><li>资源命名空间：<code>AnvilLibSync.MOD_ID</code></li></ul><h2 id="快速上手示例-使用-sync-与-lazysync" tabindex="-1">快速上手示例：使用 <code>@Sync</code> 与 <code>@LazySync</code> <a class="header-anchor" href="#快速上手示例-使用-sync-与-lazysync" aria-label="Permalink to &quot;快速上手示例：使用 `@Sync` 与 `@LazySync`&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> com.example.mymod;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dev.anvilcraft.lib.v2.sync.annotation.LazySync;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dev.anvilcraft.lib.v2.sync.annotation.Sync;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dev.anvilcraft.lib.v2.sync.util.SyncDirection;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> net.minecraft.core.BlockPos;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> net.minecraft.world.level.block.entity.BlockEntity;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> net.minecraft.world.level.block.entity.BlockEntityType;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> net.minecraft.world.level.block.state.BlockState;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Sync</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EnergyMeterBlockEntity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BlockEntity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    @</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LazySync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SyncDirection.S2C)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> storedEnergy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    @</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LazySync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SyncDirection.BOTH)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EnergyMeterBlockEntity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(BlockEntityType&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, BlockPos </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">pos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, BlockState </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        super</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(type, pos, state);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> addEnergy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> delta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.storedEnergy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delta;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // 若为 @LazySync，当持有对象已被注册追踪后，Tick 末将自动检测并差量发包</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>请确保在 <code>AnvilLibSync.getSyncManager()</code> 注册了目标对象类型与定位器（<code>SyncRegisterEntry</code>），例如方块实体通过 <code>BlockPos</code> 解析，实体通过 <code>UUID</code> 解析。内建管理器会在服务端的 <code>BlockEntity</code>、实体及注册静态类之间建立 ID 映射。</p></div><h2 id="核心枚举与注解-syncdirection、-sync、-lazysync" tabindex="-1">核心枚举与注解：<code>SyncDirection</code>、<code>@Sync</code>、<code>@LazySync</code> <a class="header-anchor" href="#核心枚举与注解-syncdirection、-sync、-lazysync" aria-label="Permalink to &quot;核心枚举与注解：`SyncDirection`、`@Sync`、`@LazySync`&quot;">​</a></h2><h3 id="syncdirection" tabindex="-1"><code>SyncDirection</code> <a class="header-anchor" href="#syncdirection" aria-label="Permalink to &quot;`SyncDirection`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>枚举常量</th><th>含义</th></tr></thead><tbody><tr><td><code>S2C</code></td><td>仅服务端向客户端单向同步；客户端试图修改不会推回服务端</td></tr><tr><td><code>C2S</code></td><td>仅客户端向服务端单向同步</td></tr><tr><td><code>BOTH</code></td><td>双向同步；任何一端修改都会推送到对端</td></tr></tbody></table><h3 id="sync-与-lazysync-属性" tabindex="-1"><code>@Sync</code> 与 <code>@LazySync</code> 属性 <a class="header-anchor" href="#sync-与-lazysync-属性" aria-label="Permalink to &quot;`@Sync` 与 `@LazySync` 属性&quot;">​</a></h3><ul><li><code>@Sync</code>：<code>SyncDirection value() default SyncDirection.BOTH;</code>（类级标记，标注所在类包含同步结构）</li><li><code>@LazySync</code>：<code>SyncDirection value() default SyncDirection.BOTH;</code>（字段级标记，交由 <code>LazySyncManager</code> 周期扫描）</li></ul><h2 id="syncproxy-t-显式同步字段包装器" tabindex="-1"><code>SyncProxy&lt;T&gt;</code>：显式同步字段包装器 <a class="header-anchor" href="#syncproxy-t-显式同步字段包装器" aria-label="Permalink to &quot;`SyncProxy&lt;T&gt;`：显式同步字段包装器&quot;">​</a></h2><p><code>SyncProxy&lt;T&gt;</code> 为任意字段提供细粒度值包装、脏标记触发及编解码控制（如无法或不想依赖字段反射替换的场景）：</p><table tabindex="0"><thead><tr><th>构造 / 方法签名</th><th>说明</th></tr></thead><tbody><tr><td><code>new SyncProxy&lt;&gt;(T value)</code></td><td>以非空初始值创建并按运行时类自动查找默认 <code>StreamCodec</code></td></tr><tr><td><code>new SyncProxy&lt;&gt;(T value, StreamCodec&lt;? extends ByteBuf, T&gt; codec)</code></td><td>显式传入自定义 <code>StreamCodec</code></td></tr><tr><td><code>new SyncProxy&lt;&gt;(Class&lt;T&gt; type)</code> / <code>new SyncProxy&lt;&gt;(StreamCodec&lt;? extends ByteBuf, T&gt; codec)</code></td><td>无初始值（允许初始 <code>null</code>）构造器</td></tr><tr><td><code>direction(SyncDirection direction)</code> / <code>setDirection(SyncDirection direction)</code></td><td>设置允许的同步流向</td></tr><tr><td><code>getValue()</code> / <code>setValue(@Nullable T value)</code></td><td>读取或修改内部值；在允许发包的逻辑侧会触发同步编码推送</td></tr><tr><td><code>setValue(B buf, boolean serverbound)</code></td><td>从网络缓冲解码并写入内部值</td></tr><tr><td><code>encode(B byteBuf)</code></td><td>将当前值按绑定的 <code>StreamCodec</code> 写入字节缓冲</td></tr></tbody></table><h2 id="管理器体系-syncmanager、lazysyncmanager-syncregisterentry" tabindex="-1">管理器体系：<code>SyncManager</code>、<code>LazySyncManager</code> &amp; <code>SyncRegisterEntry</code> <a class="header-anchor" href="#管理器体系-syncmanager、lazysyncmanager-syncregisterentry" aria-label="Permalink to &quot;管理器体系：`SyncManager`、`LazySyncManager` &amp; `SyncRegisterEntry`&quot;">​</a></h2><h3 id="syncmanager-与-syncregisterentry-t-id" tabindex="-1"><code>SyncManager</code> 与 <code>SyncRegisterEntry&lt;T, ID&gt;</code> <a class="header-anchor" href="#syncmanager-与-syncregisterentry-t-id" aria-label="Permalink to &quot;`SyncManager` 与 `SyncRegisterEntry&lt;T, ID&gt;`&quot;">​</a></h3><p><code>SyncManager</code> 维护所有注册定位策略与配置元数据：</p><ul><li><code>compileContent()</code>：收集所有同步目标并编译字段与类名映射索引；</li><li><code>contains(Class&lt;?&gt; clazz)</code>：向上遍历目标类继承链，检索匹配的 <code>SyncRegisterEntry&lt;P, ID&gt;</code>；</li><li><code>SyncRegisterEntry.create(...)</code>：将目标父类（如 <code>BlockEntity.class</code>、<code>Entity.class</code> 或静态宿主类）、唯一识别键 ID 的序列化 <code>StreamCodec</code> 及逆向查找函数 <code>Finder&lt;T, ID&gt;</code> 绑定注册。</li></ul><h3 id="lazysyncmanager" tabindex="-1"><code>LazySyncManager</code> <a class="header-anchor" href="#lazysyncmanager" aria-label="Permalink to &quot;`LazySyncManager`&quot;">​</a></h3><p>按 Tick 维护 <code>@LazySync</code> 持有者快照并执行合并推送：</p><table tabindex="0"><thead><tr><th>方法签名</th><th>说明</th></tr></thead><tbody><tr><td><code>track(@Nullable Object object)</code></td><td>手动把指定运行时实例（如未自动注册的自定义控制器）加入惰性变化跟踪集合</td></tr><tr><td><code>trackStatic(@Nullable Class&lt;?&gt; owner)</code></td><td>将整个工具类中的静态 <code>@LazySync</code> 字段加入跟踪集合</td></tr><tr><td><code>tickServer()</code> / <code>tickClient()</code></td><td>在每 Tick 结束时对比快照：对发生变化的对象生成单个聚合包 <code>LazySyncPayload</code>，写入全部改动 <code>FieldChange(configKey, blob)</code> 后按端方向发出</td></tr><tr><td><code>applyGrouped(Object object, List&lt;AppliedField&gt; fields)</code></td><td>收到对端聚合包时批量解码并写回目标对象对应字段</td></tr><tr><td><code>clearServer()</code> / <code>clearClient()</code></td><td>退出世界/关服时清理缓存快照防止内存泄漏</td></tr></tbody></table><h3 id="syncconfigmanager" tabindex="-1"><code>SyncConfigManager</code> <a class="header-anchor" href="#syncconfigmanager" aria-label="Permalink to &quot;`SyncConfigManager`&quot;">​</a></h3><p>在类加载/同步握手期统一为 <code>&quot;包名.类名#字段名&quot;</code> 分配紧凑的数字 <code>usedId</code> 索引，支持服务端在玩家登录配置阶段将映射表通过 <code>SyncConfigurationPayload</code> 同步给客户端，使运行时高频数据包仅传整型 <code>int id</code> 而非冗长全限定类名字符串。</p>',25)])])}const k=s(t,[["render",c]]);export{p as __pageData,k as default};
